arguments.file_text:
@* Vertical navigation tabs for settings sections *@

<nav class="nav nav-pills flex-column" role="tablist">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                role="tab"
                aria-selected="@(section == ActiveSection)"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>
            @section
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@inject ISettingsService SettingsService

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (profile is not null)
{
    <h4 class="mb-4">Profile Settings</h4>

    @if (successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @successMessage
            <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
        </div>
    }

    <div class="row mb-4">
        <div class="col-md-3 text-center">
            <div class="border rounded p-3 mb-2">
                @if (!string.IsNullOrWhiteSpace(profile.AvatarUrl))
                {
                    <img src="@profile.AvatarUrl" alt="Avatar" class="rounded-circle img-fluid" style="max-width: 120px; max-height: 120px;" />
                }
                else
                {
                    <div class="bg-secondary rounded-circle d-inline-flex align-items-center justify-content-center"
                         style="width: 120px; height: 120px;">
                        <span class="text-white fs-1">👤</span>
                    </div>
                }
            </div>
            <small class="text-muted text-break">@(string.IsNullOrWhiteSpace(profile.AvatarUrl) ? "No avatar set" : profile.AvatarUrl)</small>
        </div>
        <div class="col-md-9">
            <div class="mb-3">
                <label class="form-label" for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="profile.DisplayName" @bind:event="oninput" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="profile.Email" @bind:event="oninput" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="profile.Bio" @bind:event="oninput"></textarea>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
            Discard Changes
        </button>
    </div>
}

@code {
    private ProfileModel? profile;
    private ProfileModel? savedSnapshot;
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        var data = await SettingsService.GetProfileAsync();
        profile = new ProfileModel(data);
        savedSnapshot = new ProfileModel(data);
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;
        isSaving = true;
        try
        {
            var record = profile.ToRecord();
            await SettingsService.SaveProfileAsync(record);
            savedSnapshot = new ProfileModel(record);
            successMessage = "Profile saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedSnapshot is null) return;
        profile = new ProfileModel(savedSnapshot.ToRecord());
        successMessage = null;
    }

    // Mutable model wrapping the immutable record
    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile p)
        {
            DisplayName = p.DisplayName;
            Email = p.Email;
            AvatarUrl = p.AvatarUrl;
            Bio = p.Bio;
        }

        public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
    }
}

@inject ISettingsService SettingsService

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (prefs is not null)
{
    <h4 class="mb-4">Notification Preferences</h4>

    @if (successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @successMessage
            <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
        </div>
    }

    <div class="mb-4">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
                   @bind="prefs.EmailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
                   @bind="prefs.PushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
                   @bind="prefs.WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    @if (prefs.MutedChannels.Count > 0)
    {
        <h5 class="mb-3">Muted Channels</h5>
        <div class="mb-4">
            @for (int i = 0; i < prefs.MutedChannels.Count; i++)
            {
                var index = i;
                var channel = prefs.MutedChannels[index];
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"channel-{index}")"
                           checked="@mutedSet.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool?)e.Value ?? false)" />
                    <label class="form-check-label" for="@($"channel-{index}")">@channel</label>
                </div>
            }
        </div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Save Preferences
    </button>
}

@code {
    private NotifModel? prefs;
    private HashSet<string> mutedSet = new();
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var data = await SettingsService.GetNotificationPrefsAsync();
        prefs = new NotifModel(data);
        mutedSet = new HashSet<string>(data.MutedChannels);
        isLoading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedSet.Add(channel);
        else
            mutedSet.Remove(channel);
    }

    private async Task SaveAsync()
    {
        if (prefs is null) return;
        isSaving = true;
        try
        {
            var record = new NotificationPrefs(
                prefs.EmailNotifications,
                prefs.PushNotifications,
                prefs.WeeklyDigest,
                mutedSet.ToList());
            await SettingsService.SaveNotificationPrefsAsync(record);
            successMessage = "Notification preferences saved!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private class NotifModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public NotifModel(NotificationPrefs p)
        {
            EmailNotifications = p.EmailNotifications;
            PushNotifications = p.PushNotifications;
            WeeklyDigest = p.WeeklyDigest;
            MutedChannels = new List<string>(p.MutedChannels);
        }
    }
}

@inject ISettingsService SettingsService

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="() => isExpanded = !isExpanded">
        <h5 class="mb-0">Change Password</h5>
        <span>@(isExpanded ? "▲" : "▼")</span>
    </div>
    @if (isExpanded)
    {
        <div class="card-body">
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger alert-dismissible fade show" role="alert">
                    @errorMessage
                    <button type="button" class="btn-close" @onclick="() => errorMessage = null"></button>
                </div>
            }
            @if (successMessage is not null)
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @successMessage
                    <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
                </div>
            }

            <div class="mb-3">
                <label class="form-label" for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" class="form-control"
                       @bind="currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="newPassword">New Password</label>
                <input id="newPassword" type="password" class="form-control"
                       @bind="newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" class="form-control"
                       @bind="confirmPassword" />
            </div>

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
                @if (isUpdating)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool isUpdating;
    private string? errorMessage;
    private string? successMessage;

    private async Task UpdatePasswordAsync()
    {
        errorMessage = null;
        successMessage = null;

        if (string.IsNullOrWhiteSpace(currentPassword) ||
            string.IsNullOrWhiteSpace(newPassword))
        {
            errorMessage = "Please fill in all password fields.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        isUpdating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            successMessage = "Password updated successfully!";
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update password: {ex.Message}";
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@if (Sessions.Count == 0)
{
    <p class="text-muted">No active sessions.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped align-middle">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <SessionRow Session="session"
                                IsCurrent="session.Id == CurrentSessionId"
                                OnRevoke="OnRevoke" />
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnRevoke { get; set; }
}

@if (IsVisible)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session for <strong>@DeviceName</strong>? This will sign that device out immediately.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm" disabled="@IsRevoking">
                        @if (IsRevoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Revoke
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool IsVisible { get; set; }
    [Parameter] public bool IsRevoking { get; set; }
    [Parameter] public string DeviceName { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private Task Confirm() => OnConfirm.InvokeAsync();
    private Task Cancel() => OnCancel.InvokeAsync();
}

@inject ISettingsService SettingsService

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (settings is not null)
{
    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel />

    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <span class="badge @(settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
                           checked="@settings.TwoFactorEnabled" disabled />
                </div>
            </div>
            @if (settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                </small>
            }
        </div>
    </div>

    <h5 class="mb-3">Active Sessions</h5>

    <SessionTable Sessions="sessions"
                  CurrentSessionId="@sessions.FirstOrDefault()?.Id"
                  OnRevoke="RequestRevoke" />

    <RevokeConfirmDialog IsVisible="showRevokeDialog"
                         IsRevoking="isRevoking"
                         DeviceName="@revokeDeviceName"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
}

@code {
    private SecuritySettings? settings;
    private List<ActiveSession> sessions = [];
    private bool isLoading = true;

    private bool showRevokeDialog;
    private bool isRevoking;
    private string? revokeSessionId;
    private string revokeDeviceName = "";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        settings = await SettingsService.GetSecuritySettingsAsync();
        sessions = settings.Sessions.ToList();
        isLoading = false;
    }

    private void RequestRevoke(string sessionId)
    {
        revokeSessionId = sessionId;
        revokeDeviceName = sessions.FirstOrDefault(s => s.Id == sessionId)?.Device ?? "Unknown";
        showRevokeDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (revokeSessionId is null) return;
        isRevoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(revokeSessionId);
            sessions.RemoveAll(s => s.Id == revokeSessionId);
        }
        finally
        {
            isRevoking = false;
            showRevokeDialog = false;
            revokeSessionId = null;
        }
    }

    private void CancelRevoke()
    {
        showRevokeDialog = false;
        revokeSessionId = null;
    }
}

@inject ISettingsService SettingsService

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <h4 class="mb-4">Appearance Settings</h4>

    @if (successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @successMessage
            <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <h5>Theme</h5>
                @foreach (var theme in Themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(selectedTheme == theme)"
                               @onchange="() => selectedTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h5>Font Size</h5>
                @foreach (var size in FontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                               value="@size" checked="@(selectedFontSize == size)"
                               @onchange="() => selectedFontSize = size" />
                        <label class="form-check-label" for="@($"size-{size}")">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <label class="form-label" for="language"><h5 class="d-inline">Language</h5></label>
                <select id="language" class="form-select" @bind="selectedLanguage">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                           @bind="compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>
        </div>

        <div class="col-md-6">
            <AppearancePreview Theme="@selectedTheme"
                               FontSize="@selectedFontSize"
                               CompactMode="@compactMode" />
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Save
    </button>
}

@code {
    private static readonly string[] Themes = ["Light", "Dark", "System"];
    private static readonly string[] FontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;

    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var data = await SettingsService.GetAppearanceAsync();
        selectedTheme = data.Theme;
        selectedFontSize = data.FontSize;
        selectedLanguage = data.Language;
        compactMode = data.CompactMode;
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        try
        {
            await SettingsService.SaveAppearanceAsync(
                new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode));
            successMessage = "Appearance settings saved!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

