@code {
    private ProfileModel? profile;
    private ProfileModel? savedSnapshot;
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        var data = await SettingsService.GetProfileAsync();
        profile = new ProfileModel(data);
        savedSnapshot = new ProfileModel(data);
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;
        isSaving = true;
        try
        {
            var record = profile.ToRecord();
            await SettingsService.SaveProfileAsync(record);
            savedSnapshot = new ProfileModel(record);
            successMessage = "Profile saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedSnapshot is null) return;
        profile = new ProfileModel(savedSnapshot.ToRecord());
        successMessage = null;
    }

    // Mutable model wrapping the immutable record
    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile p)
        {
            DisplayName = p.DisplayName;
            Email = p.Email;
            AvatarUrl = p.AvatarUrl;
            Bio = p.Bio;
        }

        public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
    }
}

