@code {
    private NotifModel? prefs;
    private HashSet<string> mutedSet = new();
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var data = await SettingsService.GetNotificationPrefsAsync();
        prefs = new NotifModel(data);
        mutedSet = new HashSet<string>(data.MutedChannels);
        isLoading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedSet.Add(channel);
        else
            mutedSet.Remove(channel);
    }

    private async Task SaveAsync()
    {
        if (prefs is null) return;
        isSaving = true;
        try
        {
            var record = new NotificationPrefs(
                prefs.EmailNotifications,
                prefs.PushNotifications,
                prefs.WeeklyDigest,
                mutedSet.ToList());
            await SettingsService.SaveNotificationPrefsAsync(record);
            successMessage = "Notification preferences saved!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private class NotifModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public NotifModel(NotificationPrefs p)
        {
            EmailNotifications = p.EmailNotifications;
            PushNotifications = p.PushNotifications;
            WeeklyDigest = p.WeeklyDigest;
            MutedChannels = new List<string>(p.MutedChannels);
        }
    }
}

