toolArgs.file_text:
@* Vertical navigation tabs for settings sections *@

<nav class="nav nav-pills flex-column" role="tablist">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                role="tab"
                aria-selected="@(section == ActiveSection)"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>
            @section
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@inject ISettingsService SettingsService

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (profile is not null)
{
    <h4 class="mb-4">Profile Settings</h4>

    @if (successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @successMessage
            <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
        </div>
    }

    <div class="row mb-4">
        <div class="col-md-3 text-center">
            <div class="border rounded p-3 mb-2">
                @if (!string.IsNullOrWhiteSpace(profile.AvatarUrl))
                {
                    <img src="@profile.AvatarUrl" alt="Avatar" class="rounded-circle img-fluid" style="max-width: 120px; max-height: 120px;" />
                }
                else
                {
                    <div class="bg-secondary rounded-circle d-inline-flex align-items-center justify-content-center"
                         style="width: 120px; height: 120px;">
                        <span class="text-white fs-1">👤</span>
                    </div>
                }
            </div>
            <small class="text-muted text-break">@(string.IsNullOrWhiteSpace(profile.AvatarUrl) ? "No avatar set" : profile.AvatarUrl)</small>
        </div>
        <div class="col-md-9">
            <div class="mb-3">
                <label class="form-label" for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="profile.DisplayName" @bind:event="oninput" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="profile.Email" @bind:event="oninput" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="profile.Bio" @bind:event="oninput"></textarea>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
            Discard Changes
        </button>
    </div>
}

@code {
    private ProfileModel? profile;
    private ProfileModel? savedSnapshot;
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        var data = await SettingsService.GetProfileAsync();
        profile = new ProfileModel(data);
        savedSnapshot = new ProfileModel(data);
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;
        isSaving = true;
        try
        {
            var record = profile.ToRecord();
            await SettingsService.SaveProfileAsync(record);
            savedSnapshot = new ProfileModel(record);
            successMessage = "Profile saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedSnapshot is null) return;
        profile = new ProfileModel(savedSnapshot.ToRecord());
        successMessage = null;
    }

    // Mutable model wrapping the immutable record
    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile p)
        {
            DisplayName = p.DisplayName;
            Email = p.Email;
            AvatarUrl = p.AvatarUrl;
            Bio = p.Bio;
        }

        public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
    }
}

