@if (Sessions.Count == 0)
{
    <p class="text-muted">No active sessions.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped align-middle">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <SessionRow Session="session"
                                IsCurrent="session.Id == CurrentSessionId"
                                OnRevoke="OnRevoke" />
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnRevoke { get; set; }
}

@if (IsVisible)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session for <strong>@DeviceName</strong>? This will sign that device out immediately.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm" disabled="@IsRevoking">
                        @if (IsRevoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Revoke
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool IsVisible { get; set; }
    [Parameter] public bool IsRevoking { get; set; }
    [Parameter] public string DeviceName { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private Task Confirm() => OnConfirm.InvokeAsync();
    private Task Cancel() => OnCancel.InvokeAsync();
}

@inject ISettingsService SettingsService

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (settings is not null)
{
    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel />

    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <span class="badge @(settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
                           checked="@settings.TwoFactorEnabled" disabled />
                </div>
            </div>
            @if (settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                </small>
            }
        </div>
    </div>

    <h5 class="mb-3">Active Sessions</h5>

    <SessionTable Sessions="sessions"
                  CurrentSessionId="@sessions.FirstOrDefault()?.Id"
                  OnRevoke="RequestRevoke" />

    <RevokeConfirmDialog IsVisible="showRevokeDialog"
                         IsRevoking="isRevoking"
                         DeviceName="@revokeDeviceName"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
}

@code {
    private SecuritySettings? settings;
    private List<ActiveSession> sessions = [];
    private bool isLoading = true;

    private bool showRevokeDialog;
    private bool isRevoking;
    private string? revokeSessionId;
    private string revokeDeviceName = "";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        settings = await SettingsService.GetSecuritySettingsAsync();
        sessions = settings.Sessions.ToList();
        isLoading = false;
    }

    private void RequestRevoke(string sessionId)
    {
        revokeSessionId = sessionId;
        revokeDeviceName = sessions.FirstOrDefault(s => s.Id == sessionId)?.Device ?? "Unknown";
        showRevokeDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (revokeSessionId is null) return;
        isRevoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(revokeSessionId);
            sessions.RemoveAll(s => s.Id == revokeSessionId);
        }
        finally
        {
            isRevoking = false;
            showRevokeDialog = false;
            revokeSessionId = null;
        }
    }

    private void CancelRevoke()
    {
        showRevokeDialog = false;
        revokeSessionId = null;
    }
}

