+                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
+                    </div>
+                }
+            </div>
+
+            <div class="mb-4">
+                <h5>Font Size</h5>
+                @foreach (var size in FontSizes)
+                {
+                    <div class="form-check">
+                        <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
+                               value="@size" checked="@(selectedFontSize == size)"
+                               @onchange="() => selectedFontSize = size" />
+                        <label class="form-check-label" for="@($"size-{size}")">@size</label>
+                    </div>
+                }
+            </div>
+
+            <div class="mb-4">
+                <label class="form-label" for="language"><h5 class="d-inline">Language</h5></label>
+                <select id="language" class="form-select" @bind="selectedLanguage">
+                    @foreach (var lang in Languages)
+                    {
+                        <option value="@lang">@lang</option>
+                    }
+                </select>
+            </div>
+
+            <div class="mb-4">
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
+                           @bind="compactMode" />
+                    <label class="form-check-label" for="compactMode">Compact Mode</label>
+                </div>
+            </div>
+        </div>
+
+        <div class="col-md-6">
+            <AppearancePreview Theme="@selectedTheme"
+                               FontSize="@selectedFontSize"
+                               CompactMode="@compactMode" />
+        </div>
+    </div>
+
+    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
+        @if (isSaving)
+        {
+            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+        }
+        Save
+    </button>
+}
+
+@code {
+    private static readonly string[] Themes = ["Light", "Dark", "System"];
+    private static readonly string[] FontSizes = ["Small", "Medium", "Large"];
+    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];
+
+    private string selectedTheme = "Light";
+    private string selectedFontSize = "Medium";
+    private string selectedLanguage = "English";
+    private bool compactMode;
+
+    private bool isLoading = true;
+    private bool isSaving;
+    private string? successMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        isLoading = true;
+        var data = await SettingsService.GetAppearanceAsync();
+        selectedTheme = data.Theme;
+        selectedFontSize = data.FontSize;
+        selectedLanguage = data.Language;
+        compactMode = data.CompactMode;
+        isLoading = false;
+    }
+
+    private async Task SaveAsync()
+    {
+        isSaving = true;
+        try
+        {
+            await SettingsService.SaveAppearanceAsync(
+                new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode));
+            successMessage = "Appearance settings saved!";
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+}
+

